package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.view.KeyEvent;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Disposable AVD only. Synthetic records, mocked model/search; no real key or user phone. */
public class ChatRedesignTest extends ChatExperienceTest {
 void holdAutomation()throws Exception{h.js("Object.defineProperty(document,'hidden',{configurable:true,get:()=>true})");}
 @Override void sendText(String text)throws Exception{int before=chat().getJSONArray("messages").length();h.js("document.querySelector('#chat-input').value="+JSONObject.quote(text)+";document.querySelector('#chat-input').dispatchEvent(new Event('input'))");click("[data-action=send]");until("document.querySelectorAll('.chat-message').length>="+(before+2)+"&&!document.querySelector('.loading')");}
 void seedRedesign()throws Exception{check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.0"),"Seed on signed previous version");holdAutomation();JSONObject data=init();try(TrackStore t=new TrackStore(getTargetContext())){data.put("gpx",t.gpx("2026-12-15")).put("raw",t.diagnostics("2026-12-15").getJSONArray("rawPoints"));}try(FileOutputStream out=getTargetContext().openFileOutput("chat-redesign-upgrade.json",0)){out.write(data.toString().getBytes("UTF-8"));}}
 JSONObject baseline()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("chat-redesign-upgrade.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}
 void verifyUpgrade()throws Exception{JSONObject before=baseline(),after=init();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.1"),"Signed 1.7.1 / code20 installed over 1.7.0");for(String key:new String[]{"records","messages","wikiPages","chatSession"})check(before.get(key).toString().equals(after.get(key).toString()),"Upgrade preserves "+key);JSONObject a=before.getJSONObject("settings"),b=after.getJSONObject("settings");a.remove("wikiAutomation");b.remove("wikiAutomation");check(a.toString().equals(b.toString()),"Upgrade preserves model and current link-search configuration");try(TrackStore t=new TrackStore(getTargetContext())){check(before.getString("gpx").equals(t.gpx("2026-12-15"))&&before.getJSONArray("raw").toString().equals(t.diagnostics("2026-12-15").getJSONArray("rawPoints").toString()),"GPS raw and D trajectory unchanged");}}
 void checkUi()throws Exception{
  holdAutomation();chatMock();h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY")).put("dailyLearningGoal",87)));h.call("newChat",new JSONObject());reload();holdAutomation();chatMock();click("[data-page=chat]");Thread.sleep(400);
  jsCheck("getComputedStyle(document.querySelector('.app-header')).display==='none'","No extra brand/model header in AI chat");jsCheck("document.querySelectorAll('.chat-toolbar').length===1&&!document.querySelector('.chip-row')","One compact toolbar; no stacked suggestion/config panels");jsCheck("document.querySelector('.chat-send').disabled","Empty message cannot be sent");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Chat fits phone width");
  h.screenshot("chat-home-1.7.1.png");click("[data-action=chat-history]");until("document.querySelector('#chat-history-drawer').open");Thread.sleep(250);
  h.screenshot("chat-history-1.7.1.png");jsCheck("(()=>{const r=document.querySelector('#chat-history-drawer').getBoundingClientRect();return r.left===0&&r.top===0&&r.height>innerHeight-2&&r.width<innerWidth})()","History is left-side full-height drawer, not bottom-sheet form: "+h.js("(()=>{let r=document.querySelector('#chat-history-drawer').getBoundingClientRect();return [r.left,r.top,r.width,r.height,innerWidth,innerHeight]})()"));jsCheck("document.querySelector('#drawer-model')!==null&&getComputedStyle(document.querySelector('#open-settings')).display!=='none'&&getComputedStyle(document.querySelector('.app-header')).display==='none'","Model configuration has one visible entry inside drawer");
  h.screenshot("chat-history-1.7.1.png");jsCheck("getComputedStyle(document.querySelector('[data-delete-session]')).display==='none'","History hides destructive buttons until management");click("#drawer-manage");jsCheck("getComputedStyle(document.querySelector('[data-delete-session]')).display==='flex'","Manage explicitly reveals deletion controls");click("#drawer-manage");h.js("window.appBack()");jsCheck("!document.querySelector('#chat-history-drawer').open&&document.querySelector('#chat-input')!==null","Android back dismisses drawer without leaving chat");
  sendText("合成项目青禾的目标35分钟，请记住。");sendText("上条说的项目目标是什么？只回答这件事。");jsCheck("__calls.filter(p=>p.tool.name==='prepare_life_records').at(-1).messages.some(m=>typeof m.content==='string'&&m.content.includes('青禾'))","New UI retains multi-turn context and structured reply");
  h.js("document.querySelector('#chat-input').value='未发送草稿\\n第二行';document.querySelector('#chat-input').dispatchEvent(new Event('input'))");click("[data-action=chat-history]");click("[data-session='"+chat().getJSONObject("session").getString("id")+"']");jsCheck("document.querySelector('#chat-input').value.includes('未发送草稿')&&!document.querySelector('#confirm-dialog').open","Reopening current conversation preserves draft without destructive-switch dialog");
  click("[data-action=chat-history]");click("#drawer-new");until("document.querySelector('#confirm-dialog').open");click("#confirm-cancel");jsCheck("document.querySelector('#chat-history-drawer').open","Canceled switch retains current drawer and draft");click("#drawer-new");click("#confirm-ok");until("document.querySelector('.chat-welcome')!==null");jsCheck("document.querySelector('#chat-input').value===''","Confirmed new conversation starts empty");
  String token="蓝鲸索引"+System.nanoTime(),literal="100%_literal"+System.nanoTime();String sid=chat().getJSONObject("session").getString("id");h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","redesign-search-"+System.nanoTime()).put("sessionId",sid).put("role","user").put("text","普通标题").put("createdAt",System.currentTimeMillis())));h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","redesign-content-"+System.nanoTime()).put("sessionId",sid).put("role","assistant").put("text","正文唯一词"+token+" <img src=x> "+literal).put("createdAt",System.currentTimeMillis())));
  String active=chat().getJSONObject("session").getString("id");JSONArray matches=(JSONArray)h.call("searchChats",new JSONObject().put("query",token));check(matches.length()==1&&matches.getJSONObject(0).getString("id").equals(sid),"Native history searches actual body text, not title only");check(chat().getJSONObject("session").getString("id").equals(active),"History search does not change active conversation");check(((JSONArray)h.call("searchChats",new JSONObject().put("query",literal))).length()==1,"Percent and underscore search literally, not SQL wildcards");
  reload();holdAutomation();chatMock();click("[data-page=chat]");click("[data-action=chat-history]");h.js("document.querySelector('#chat-history-search').value="+JSONObject.quote(token)+";document.querySelector('#chat-history-search').dispatchEvent(new Event('input'))");until("document.querySelectorAll('#chat-history-results [data-session]').length===1&&document.querySelector('#chat-history-results').innerText.includes('蓝鲸索引')");jsCheck("!document.querySelector('#chat-history-results img')","Search snippet is escaped and cannot inject HTML");h.screenshot("chat-search-1.7.1.png");click("#chat-history-close");
  click("[data-action=chat-tools]");jsCheck("!document.querySelector('#chat-links')&&!document.querySelector('#link-settings-form')","Link-search configuration button removed");click("#chat-wiki");jsCheck("!document.querySelector('#wiki-retry')&&!document.querySelector('#wiki-backfill')&&!document.querySelector('#wiki-auto-form')","Wiki page is read-only without manual compilation controls");if(h.js("document.querySelector('[data-wiki-page]')!==null").equals("true")){click("[data-wiki-page]");jsCheck("!document.querySelector('#refresh-wiki')","Wiki detail has no update/configure button");}click("#close-editor");
  click("[data-action=chat-history]");click("#drawer-model");jsCheck("document.querySelector('#api-key')!==null&&!document.querySelector('#link-settings-form')&&!document.querySelector('#wiki-auto-form')","Drawer model entry opens model-only page");click(".model-back");jsCheck("document.querySelector('#chat-input')!==null","Model return restores chat");
  // Native history initialization is idempotent; it does not require a UI button.
  getTargetContext().getSharedPreferences("wiki-automation",0).edit().remove("internal-backfill-v1").commit();JSONArray jobs=queue().getJSONArray("jobs");check(queue().getInt("count")>0,"Existing knowledge records auto-enqueue internally on first run");while(queue().getInt("count")>0)h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));check(queue().getInt("count")==0,"Repeated queue reads do not backfill history endlessly");
  String rid="redesign-auto-"+System.nanoTime();h.call("saveRecord",new JSONObject().put("record",note(rid,"合成知识库新增记录，在内部自动归类，无需点击编译。")).put("allowDuplicate",true));reload();chatMock();h.js("AutoWiki.resume()");for(int i=0;i<300&&queue().getInt("count")>0;i++)Thread.sleep(100);check(queue().getInt("count")==0&&find(rid).has("wikiTopics"),"New records automatically classified and compiled without manual setup");jsCheck("__calls.some(p=>p.automaticWiki&&p.tool.name==='compile_learning_wiki')","Internal defaults actually call Wiki compiler");
  click("[data-page=chat]");h.call("newChat",new JSONObject());reload();chatMock();click("[data-page=chat]");h.screenshot("chat-home-1.7.1.png");
 }
 void keyboardUi()throws Exception{holdAutomation();chatMock();click("[data-page=chat]");Thread.sleep(350);int height=new JSONArray(h.js("[innerHeight]")).getInt(0);h.tap("#chat-input",false);until("innerHeight<"+(height-100));until("document.body.classList.contains('chat-keyboard')");jsCheck("getComputedStyle(document.querySelector('.bottom-nav')).display==='none'","Real keyboard hides bottom navigation to free chat space");h.screenshot("chat-keyboard-1.7.1.png");jsCheck("(()=>{let r=document.querySelector('.composer').getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight+1})()","Real keyboard leaves whole input composer visible: "+h.js("(()=>{let r=document.querySelector('.composer').getBoundingClientRect();return [r.top,r.bottom,innerHeight]})()"));h.js("document.querySelector('#chat-input').value='键盘与多行测试\\n第二行\\n第三行';document.querySelector('#chat-input').dispatchEvent(new Event('input'))");jsCheck("!document.querySelector('.chat-send').disabled","Typing enables actual send control");Thread.sleep(1500);h.screenshot("chat-keyboard-1.7.1.png");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);until("innerHeight>="+(height-30));until("!document.body.classList.contains('chat-keyboard')");jsCheck("getComputedStyle(document.querySelector('.bottom-nav')).display!=='none'&&document.querySelector('#chat-input').value.includes('第三行')","Closing keyboard restores navigation and retains draft");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Narrow chat composer has no horizontal overflow");h.js("document.querySelector('#chat-input').value='';document.querySelector('#chat-input').dispatchEvent(new Event('input'))");click("[data-action=chat-history]");Thread.sleep(250);jsCheck("(()=>{const r=document.querySelector('#drawer-model').getBoundingClientRect();return r.top>0&&r.bottom<innerHeight})()","Drawer model control remains reachable on narrow screen");h.screenshot("chat-narrow-drawer-1.7.1.png");}
 @Override public void onStart(){Bundle out=new Bundle();try{h=new MainHost(this);h.open();if(phase.equals("seed-redesign"))seedRedesign();else if(phase.equals("keyboard"))keyboardUi();else{holdAutomation();if(phase.equals("verify"))verifyUpgrade();checkUi();}out.putString("stream","PASS "+passed+" redesigned chat checks; phase="+phase+"\n");finish(Activity.RESULT_OK,out);}catch(Throwable ex){out.putString("stream","FAIL after "+passed+": "+ex+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
